from pathlib import Path
import json,subprocess,hashlib
P=Path(__file__).resolve().parent;src=P.parent/'final_remotion_ai_video_workflow.mp4';m=json.loads((P/'src/edit-manifest.json').read_text())
r=json.loads(subprocess.check_output(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(src)]));v=next(s for s in r['streams'] if s['codec_type']=='video');a=next(s for s in r['streams'] if s['codec_type']=='audio')
assert (v['width'],v['height'],v['r_frame_rate'])==(1280,720,'30/1');assert int(v['nb_read_frames'])==m['composition']['durationInFrames'];assert a['sample_rate']=='48000';assert a['channels']==2
subprocess.run(['ffmpeg','-v','error','-i',str(src),'-f','null','-'],check=True)
res=subprocess.run(['ffmpeg','-hide_banner','-i',str(src),'-af','loudnorm=I=-18:TP=-1:LRA=11:print_format=json','-f','null','-'],capture_output=True,text=True,check=True);stats=json.JSONDecoder().raw_decode(res.stderr[res.stderr.rfind('{'):])[0];(P/'out/final_loudness.json').write_text(json.dumps(stats,indent=2));assert float(stats['input_tp'])<0
report={'file':src.name,'sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'bytes':src.stat().st_size,'durationSeconds':m['composition']['durationInFrames']/30,'video':{'codec':v['codec_name'],'width':v['width'],'height':v['height'],'fps':v['r_frame_rate'],'frames':v['nb_read_frames']},'audio':{'codec':a['codec_name'],'sampleRate':48000,'channels':2,'integratedLUFS':stats['input_i'],'truePeakDbTP':stats['input_tp'],'loudnessRangeLU':stats['input_lra']},'fullDecode':'pass','subtitleTimingAndWidth':'pass','visualReview':'See review.md, remotion/out/audit_v3 and remotion/out/final_news.png','audioReview':'VOICEVOX kana plus automated ASR; subjective continuous listening is not available in this tool environment.','newPaidVideoGeneration':False,'published':False}
(P.parent/'delivery.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps(report,ensure_ascii=False,indent=2))
